<?php
require_once __DIR__.'/includes/auth.php';require_login();$uid=current_user_id();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$uid]);header('Location: notifications.php');exit;}$st=$pdo->prepare('SELECT n.*,c.title,c.conversation_type FROM notifications n LEFT JOIN conversations c ON c.conversation_id=n.conversation_id WHERE n.user_id=? ORDER BY n.created_at DESC LIMIT 100');$st->execute([$uid]);$items=$st->fetchAll();$pageTitle='Notifications';require __DIR__.'/includes/header.php';?><section class="standalone-panel"><a class="back-link" href="dashboard.php">← Back to messages</a><div class="panel-heading"><h1>Notifications</h1><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="button button-ghost button-small" type="submit">Mark all read</button></form></div><?php if(!$items): ?><div class="empty-state"><h3>You're all caught up</h3><p>New message notifications will appear here.</p></div><?php else: ?><div class="notification-list"><?php foreach($items as $n): ?><a class="notification-row <?= !$n['is_read']?'unread':'' ?>" href="<?= $n['conversation_id']?'chat.php?id='.(int)$n['conversation_id']:'notifications.php' ?>"><span class="notification-dot"></span><span><strong><?= e($n['body']) ?></strong><small><?= e(date('M j, Y · H:i',strtotime($n['created_at']))) ?></small></span></a><?php endforeach; ?></div><?php endif; ?></section><?php require __DIR__.'/includes/footer.php';?>
